use std::io::{Cursor, Read};

fn main() {
    let malformed = [0x28, 0xb5, 0x2f, 0xfd, 0, 0, 0x0b, 0x20, 0, b'x'];
    let mut decoded = Vec::new();
    let result = ruzstd::decoding::StreamingDecoder::new(Cursor::new(malformed))
        .map_err(std::io::Error::other)
        .and_then(|mut reader| reader.read_to_end(&mut decoded));
    println!("ruzstd=0.8.2 window_bytes=1024 result={result:?} emitted_bytes={}", decoded.len());
    assert!(result.is_err(), "malformed block must not exceed its declared window");
    assert!(decoded.is_empty(), "rejected first block must not emit payload");
}
